// Puzzle data shapes. Levels are generated by scripts/puzzles/generate.mjs.

/** [horizontal (1) or vertical (0), length, fixed row/column, position]. */
export type SlideBlock = [horizontal: 0 | 1, length: number, fixed: number, pos: number];

export interface SlideLevel {
  id: string;
  /** Optimal number of moves (one move = one block, any distance). */
  minMoves: number;
  /** Block 0 is the red one; it leaves through the right edge of EXIT_ROW. */
  blocks: SlideBlock[];
}

/** [x, y, bridges needed]. */
export type BridgesIsland = [x: number, y: number, n: number];

export interface BridgesLevel {
  id: string;
  width: number;
  height: number;
  islands: BridgesIsland[];
}

export type DailyPuzzle =
  | { kind: "slide"; number: number; level: SlideLevel }
  | { kind: "bridges"; number: number; level: BridgesLevel };

export const SLIDE_SIZE = 6;
export const SLIDE_EXIT_ROW = 2;
